import json

def process_memory(memory, facts, updates):
    action = "keep"
    for fact in facts:
        if fact["id"] in memory["supports"]:
            action = "withdraw"
            break
        elif fact["id"] in memory["needs"]:
            action = "recompute"
            break
        elif fact["id"] in memory["doubts"]:
            action = "uncertain"
            break

    for update in updates:
        if update["id"] in memory["supports"]:
            memory["supports"].remove(update["id"])
        elif update["id"] in memory["needs"]:
            memory["needs"].remove(update["id"])
        elif update["id"] in memory["doubts"]:
            memory["doubts"].remove(update["id"])

    if action == "withdraw":
        if not memory["needs"]:
            return "withdraw"
    elif action == "recompute":
        if not memory["needs"]:
            return "recompute"
    elif action == "uncertain":
        if not memory["needs"]:
            return "uncertain"

    return "keep"

def process_memories(memories, facts, updates):
